   COMMENT ON TABLE serving.medicaid_drug_quarterly IS 'Medicaid state drug utilization (CMS State Drug Utilization Data, 2024), aggregated by state, quarter, drug class and drug. Four classes: GLP-1, insulin, DPP-4, metformin. SGLT2 inhibitors are not included. Built by the diabetes-glp1-pipeline project.';
   COMMENT ON COLUMN serving.medicaid_drug_quarterly.state IS 'Two-letter state code';
   COMMENT ON COLUMN serving.medicaid_drug_quarterly.year IS 'Calendar year of the reporting period';
   COMMENT ON COLUMN serving.medicaid_drug_quarterly.quarter IS 'Calendar quarter, 1 to 4';
   COMMENT ON COLUMN serving.medicaid_drug_quarterly.drug_class IS 'Drug class assigned by the pipeline keyword seed: GLP-1, Insulin, DPP-4 or Metformin';
   COMMENT ON COLUMN serving.medicaid_drug_quarterly.drug IS 'Drug name matched by the pipeline keyword seed';
   COMMENT ON COLUMN serving.medicaid_drug_quarterly.prescriptions IS 'Number of prescriptions reimbursed. The source may suppress small cells, so totals can understate.';
   COMMENT ON COLUMN serving.medicaid_drug_quarterly.spend IS 'Total amount reimbursed in US dollars, as reported in the source field total_amount_reimbursed';

   COMMENT ON TABLE serving.clinic_daily IS 'SYNTHETIC. Daily scheduled, completed and no-show appointment counts by clinic and department, generated by api/scripts/generate_clinic_ops.ts with a fixed seed. Not real data.';
   COMMENT ON COLUMN serving.clinic_daily.day IS 'Calendar date, weekdays only';
   COMMENT ON COLUMN serving.clinic_daily.clinic_id IS 'Clinic number, 1 or 2';
   COMMENT ON COLUMN serving.clinic_daily.department IS 'Primary care, Behavioral health or Endocrinology';
   COMMENT ON COLUMN serving.clinic_daily.scheduled IS 'Appointments scheduled that day';
   COMMENT ON COLUMN serving.clinic_daily.completed IS 'Scheduled appointments minus no-shows';
   COMMENT ON COLUMN serving.clinic_daily.no_shows IS 'Appointments where the patient did not attend';

   COMMENT ON TABLE serving.kpi_demo IS 'Hand-written demo rows from early development. No longer shown in the app.';

   COMMENT ON TABLE clinical.patients IS 'SYNTHETIC patient rows that demonstrate column grants and row-level security. Clinicians see only their own clinic and only non-identifying columns.';
   COMMENT ON COLUMN clinical.patients.patient_id IS 'Surrogate key';
   COMMENT ON COLUMN clinical.patients.clinic_id IS 'Clinic the patient belongs to; drives row-level security';
   COMMENT ON COLUMN clinical.patients.full_name IS 'Fake name; not granted to any app role';
   COMMENT ON COLUMN clinical.patients.birth_date IS 'Fake birth date; not granted to any app role';
   COMMENT ON COLUMN clinical.patients.birth_year IS 'Birth year derived from birth_date';
   COMMENT ON COLUMN clinical.patients.city IS 'City of residence';
   COMMENT ON COLUMN clinical.patients.primary_condition IS 'Main diagnosis label';

   COMMENT ON TABLE app.users IS 'Application accounts: role, clinic and password hash. Readable by the API login for sign-in and by the admin role.';
   COMMENT ON TABLE app.audit_log IS 'Every login and data view, written by all roles and readable only by admin.';